layer.css:
[data-ryt="pitch"] { color: #8d8d8d; border-radius: 0px; font-family: monaco, menlo, monospace; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(224, 224, 224); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
article[data-ryt="rec-card"] { background-color: color-mix(in srgb, var(--ryt-bg) 5%, transparent); border-top: 1px solid color-mix(in srgb, var(--ryt-bg) 10%, transparent); border-right: 1px solid color-mix(in srgb, var(--ryt-bg) 10%, transparent); border-bottom: 1px solid color-mix(in srgb, var(--ryt-bg) 10%, transparent); border-left: 1px solid color-mix(in srgb, var(--ryt-bg) 10%, transparent); border-radius: 15px; transition: 0.3s }
[data-ryt="footer"] { background-color: rgba(0, 0, 0, 0.3); border-top: 1px solid color-mix(in srgb, var(--ryt-bg) 10%, transparent); font-style: normal; letter-spacing: normal; text-transform: none; color: var(--ryt-text) }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: #059ab8; border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(0, 212, 255); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="category"], [data-ryt="tags"] li { color: #888888; background-color: color-mix(in srgb, var(--ryt-bg) 5%, transparent); border-top: 1px solid color-mix(in srgb, var(--ryt-bg) 10%, transparent); border-right: 1px solid color-mix(in srgb, var(--ryt-bg) 10%, transparent); border-bottom: 1px solid color-mix(in srgb, var(--ryt-bg) 10%, transparent); border-left: 1px solid color-mix(in srgb, var(--ryt-bg) 10%, transparent); border-radius: 20px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 16px; padding-bottom: 8px; padding-left: 16px; transition: 0.3s }
[data-ryt="review"] { color: #888888; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 14.4px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: #818181; border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(240, 240, 240); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.3s }
body { background-image: linear-gradient(135deg, rgb(10, 10, 10) 0%, rgb(26, 26, 46) 100%); background-size: auto; background-position: 0% 0%; background-repeat: repeat }
[data-ryt="rec-card"] [data-ryt="title"] { color: #888888; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18.72px; font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="category"]:hover, [data-ryt="tags"] li:hover { border-top-color: transparent; border-right-color: transparent; border-bottom-color: transparent; border-left-color: transparent }
article[data-ryt="rec-card"]:hover { transform: translateY(-5px); box-shadow: rgba(0, 212, 255, 0.2) 0px 15px 30px }
